/**
 * Checks if a character is a Bengali dependent vowel sign or combining mark that
 * triggers HarfBuzz/Minikin to synthesize a U+25CC (Dotted Circle ◌) when rendered
 * standalone in a text view.
 */
fun isBengaliCombiningChar(c: Char): Boolean {
  return c in 'ঁ'..'ঃ' || // Candrabindu, Anusvara, Visarga
    c == '়' || // Nukta
    c in 'া'..'ৄ' || // Vowel signs aa, i, ii, u, uu, rri, rrii
    c in 'ে'..'ৈ' || // Vowel signs e, ai
    c in 'ো'..'্' || // Vowel signs o, au, Virama / hasanta
    c == 'ৗ' // AU length mark
}

private fun cleanCombiningMarkLabel(label: String): String {
  if (label.isEmpty()) return ""
  var needsClean = label.first().isWhitespace() || label.last().isWhitespace()
  if (!needsClean) {
    for (i in 0 until label.length) {
      val ch = label[i]
      if (ch == '\u200C' || ch == '\u200D' || ch == '\u25CC') {
        needsClean = true
        break
      }
    }
  }
  if (!needsClean) return label
  return label
    .replace("\u200C", "")
    .replace("\u200D", "")
    .replace("\u25CC", "")
    .trim()
}

/**
 * Checks if a key label string is a Bengali combining mark or two-part vowel sign.
 */
fun isBengaliCombiningLabel(label: String): Boolean {
  val clean = cleanCombiningMarkLabel(label)
  if (clean.isEmpty()) return false
  if (clean.length == 1) {
    return isBengaliCombiningChar(clean[0])
  }
  return clean == "ো" || clean == "ৌ"
}

