  init {
    rawPathMap.forEach { (charKey, svgData) ->
      try {
        val androidPath = PathParser.createPathFromPathData(svgData)
        pathCache[charKey] = androidPath.asComposePath()
      } catch (_: Exception) {
      }
    }
  }

  fun getPath(charKey: String): Path? = pathCache[charKey]
}

/**
 * Standalone Bengali combining mark renderer using authentic Noto Sans Bengali outlines.
 * Scaled proportionally to [fontSize] and centered within the available space.
 */
@Composable
fun BengaliCombiningMark(
  markString: String,
  color: Color,
  fontSize: TextUnit,
  modifier: Modifier = Modifier,
) {
  val clean = androidx.compose.runtime.remember(markString) { cleanCombiningMarkLabel(markString) }
  val path = androidx.compose.runtime.remember(clean) { BengaliGlyphPaths.getPath(clean) }

  val scaleMultiplier =
    when (clean) {
      "ু", "ূ", "ৃ", "্" -> 1.0f
      "ঁ" -> 1.02f
      "ঃ" -> 1.0f
      else -> 1.0f
    }

  if (path != null) {
    Canvas(modifier = modifier) {
      val fontPx = fontSize.toPx()
      val scale = (fontPx / 1000f) * scaleMultiplier
      withTransform({
        translate(size.width / 2f, size.height / 2f)
        scale(scale, scale, Offset.Zero)
      }) {
        drawPath(path = path, color = color)
      }
    }
  } else {
    Box(modifier = modifier, contentAlignment = Alignment.Center) {
      Text(
        text = clean,
        color = color,
        fontSize = fontSize,
        fontFamily = BengaliFontFamily,
        style =
          TextStyle(
            platformStyle = PlatformTextStyle(includeFontPadding = false),
            textAlign = TextAlign.Center,
          ),
      )
    }
  }
}
